1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
2	import { multiParams } from './params';
3	
4	export type ClientMsg =
5	  | { t: 'join'; name: string; kind?: 'walk' | 'drive'; ch?: number; veh?: number }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ). ch: nhân vật (0 nam, 1 nữ) của người đi dạo hoặc người đi xe máy; khách cũ không gửi = nam. veh: 1 = xe máy, chỉ kèm kind 'drive'; không có = ô tô (khách cũ)
6	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
7	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
8	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad; xe máy: bkLeanToWire(độ nghiêng)); không có bank / pose
9	  | { t: 'hb' }
10	  | { t: 'leave' };
11	
12	export interface Flyer { slot: number; name: string; ch?: number; veh?: number }   // ch: nhân vật của người đi dạo / người đi xe máy (walkers, drivers; máy chủ cũ không gửi = nam); veh: loại xe (chỉ drivers; 1 xe máy, máy chủ cũ không gửi = ô tô)
13	
14	/* Nhân vật đi dạo hợp lệ: 1 = nữ, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 nam */
15	export function exCharNorm(v: unknown): number { return v === 1 ? 1 : 0; }
16	
17	/* Loại xe hợp lệ của chỗ lái: 1 = xe máy, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 ô tô */
18	export function exVehNorm(v: unknown): number { return v === 1 ? 1 : 0; }
19	
20	/* Độ nghiêng xe máy qua trường st: máy chủ kẹp st ở ±drive.steerMax (0,56 rad, góc lái ô tô) nên gửi lean × BK_WIRE (độ nghiêng 0,7 rad vẫn lọt), bên nhận chia lại.
21	   Khách cũ thấy xe máy thành ô tô bẻ lái theo st (chấp nhận, spec §17.4). Số lạ (NaN) → 0 */
