1	/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { exSanitizeName, exCharNorm, exVehNorm } from '../../../src/explore/multi/protocol';
4	import type { ServerMsg, Flyer, Kind } from '../../../src/explore/multi/protocol';
5	import { exIsBad } from './badwords';
6	
7	export type Out = { to: string | 'all'; msg: ServerMsg };
8	
9	// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; người lái: [slot, x, y, z, yaw, v, st, giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
10	// ch: nhân vật người đi dạo / người đi xe máy chọn (0 nam, 1 nữ), dùng ở nhóm đi dạo và chỗ lái xe máy; phát kèm walkers / drivers của lobby để mọi khách (cả người vào sau) vẽ đúng
11	// veh: loại xe của chỗ lái (0 ô tô, 1 xe máy), chỉ dùng ở nhóm lái; ô tô luôn ch 0
12	interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean; ch: number; veh: number }
13	interface Conn { stamps: number[] }
14	
15	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
16	const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]
17	
18	export class SkyRoom {
19	  private conns = new Map<string, Conn>();
20	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
21	  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
22	  private driveSlots: (Slot | null)[] = new Array(P.drive.slots).fill(null);   // nhóm chỗ lái xe, tách khỏi hai nhóm kia
23	  private lastBroadcast = -Infinity;
24	
25	  private lobby(): Out {
26	    const flyers: Flyer[] = [];
27	    const walkers: Flyer[] = [];
28	    const drivers: Flyer[] = [];
29	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
30	    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name, ch: s.ch }); });
31	    this.driveSlots.forEach((s, i) => { if (s) drivers.push({ slot: i, name: s.name, ch: s.ch, veh: s.veh }); });   // khách cũ bỏ qua ch / veh
32	    return { to: 'all', msg: { t: 'lobby', flyers, walkers, drivers } };
33	  }
34	
35	  connect(id: string, now: number): Out[] | null {
36	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
37	    this.conns.set(id, { stamps: [] });
38	    return [{ to: id, msg: this.lobby().msg }];
39	  }
40	
41	  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay
42	
43	  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo
44	
45	  driveSlotOf(id: string): number { return this.driveSlots.findIndex(s => s !== null && s.id === id); }   // slot lái xe, -1 nếu không lái
46	
47	  chOf(id: string): number { const w = this.walkSlotOf(id); if (w >= 0) return this.walkSlots[w].ch; const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].ch; }   // nhân vật của người đi dạo / đi xe máy (để lưu vào attachment); 0 nếu không
48	
49	  vehOf(id: string): number { const d = this.driveSlotOf(id); return d < 0 ? 0 : this.driveSlots[d].veh; }   // loại xe của người lái (để lưu vào attachment); 0 nếu ô tô hoặc không lái
50	
51	  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : this.driveSlotOf(id) >= 0 ? 'drive' : null; }
52	
53	  hasFlyers(): boolean { return [this.slots, this.walkSlots, this.driveSlots].some(g => g.some(s => s !== null)); }   // còn ai giữ slot (bay, đi hoặc lái): giữ alarm quét
54	
55	  private groupOf(kind: Kind | null): (Slot | null)[] { return kind === 'walk' ? this.walkSlots : kind === 'drive' ? this.driveSlots : this.slots; }
56	
57	  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
58	  seenOf(id: string): number {
59	    const i = this.slotOf(id);
60	    if (i >= 0) return this.slots[i].seen;
61	    const w = this.walkSlotOf(id);
62	    if (w >= 0) return this.walkSlots[w].seen;
63	    const d = this.driveSlotOf(id);
64	    return d < 0 ? -1 : this.driveSlots[d].seen;
65	  }
66	
67	  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
68	     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
69	  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number; veh?: number }[], now: number): void {
70	    for (const e of list) {
71	      const group = this.groupOf(e.kind === 'walk' || e.kind === 'drive' ? e.kind : 'fly');
72	      if (e.slot < 0 || e.slot >= group.length) continue;
73	      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
74	      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
75	      const veh = e.kind === 'drive' ? exVehNorm(e.veh) : 0;   // attachment cũ không có veh: ô tô
76	      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false, ch: e.kind === 'walk' || veh === 1 ? exCharNorm(e.ch) : 0, veh };
77	    }
78	  }
79	
80	  message(id: string, raw: string, now: number): Out[] {
81	    const conn = this.conns.get(id);
82	    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
83	    let m: any;
84	    try { m = JSON.parse(raw); } catch { return []; }
85	    if (!m || typeof m !== 'object') return [];
86	    const kind = this.kindOf(id);   // loại theo slot kết nối đang giữ, không theo trường trong gói
87	    const group = this.groupOf(kind);
