117	    for (const v of [x, y, z, yaw, tilt, st]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
118	    conn.stamps = conn.stamps.filter(t => now - t < 1000);
119	    if (conn.stamps.length >= P.posMaxPerSec) return [];
120	    conn.stamps.push(now);
121	    s.seen = now;
122	    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
123	    if (drive) {
