125	      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, D.yMin, D.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(tilt, -D.vMax, D.vMax), clamp(st, -D.steerMax, D.steerMax), stamp];
126	    } else if (walk) {
127	      const B = P.stroll.bounds;
128	      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
129	    } else {
130	      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
131	    }
132	    s.dirty = true;
