136	  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
137	     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
138	  private flush(now: number): Out[] {
139	    if (now - this.lastBroadcast < P.broadcastMs) return [];
140	    const f: number[][] = [], w: number[][] = [], d: number[][] = [];
141	    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
142	    for (const t of this.walkSlots) if (t && t.dirty) { w.push(t.pos!); t.dirty = false; }
143	    for (const t of this.driveSlots) if (t && t.dirty) { d.push(t.pos!); t.dirty = false; }
144	    if (!f.length && !w.length && !d.length) return [];
145	    this.lastBroadcast = now;
146	    // f luôn có (khách cũ đọc m.f); w / d chỉ có khi có người cử động, khách cũ bỏ qua trường lạ
147	    const msg: { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] } = { t: 'pos', f };
148	    if (w.length) msg.w = w;
149	    if (d.length) msg.d = d;
150	    return [{ to: 'all', msg }];
151	  }
