153	  // Trả slot của kết nối; true nếu có slot được trả
154	  private release(id: string): boolean {
155	    const i = this.slotOf(id);
156	    if (i >= 0) { this.slots[i] = null; return true; }
157	    const w = this.walkSlotOf(id);
158	    if (w >= 0) { this.walkSlots[w] = null; return true; }
159	    const d = this.driveSlotOf(id);
160	    if (d < 0) return false;
161	    this.driveSlots[d] = null;
162	    return true;
163	  }
164	
165	  disconnect(id: string): Out[] {
166	    this.conns.delete(id);
167	    return this.release(id) ? [this.lobby()] : [];
168	  }
169	
170	  sweep(now: number): Out[] {
171	    const out: Out[] = [];
172	    for (const group of [this.slots, this.walkSlots, this.driveSlots]) group.forEach((s, i) => {
173	      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); group[i] = null; }
174	    });
175	    if (out.length) out.push(this.lobby());
176	    return out;
177	  }
