  kinds.forEach((k, g) => { for (let i = 0; i < 5; i++) { const id = k + i; ids.push(id); mk(r, id, k, k.toUpperCase() + i, i * 5, 10 + g * 3, g * 5, 0); } });
  const o = chat(r, 'walk0', 'đông quá', 500);
